        if(!ready)return;if("database".equals(screen))saveScope();rememberDatabaseScroll();handler.removeCallbacks(filterRequest);searchGeneration++;if(searchTask!=null){searchTask.cancel(true);searchTask=null;}cancelTask();ComputerReview.pause();handler.removeCallbacks(reviewRefresh);screen=name;if(!standaloneOptions)prefs.edit().putString("screen",name).apply();
