        setupBoard=board();setupBoard.setContentDescription("New game board preview");setupBoard.setPosition(Position.fromFen(startFen),"",false);setupBoard.setFlipped(setupFlip);LinearLayout.LayoutParams boardSize=new LinearLayout.LayoutParams(-1,-2);boardSize.bottomMargin=dp(10);body.addView(setupBoard,boardSize);
        LinearLayout difficulty=settingsGroup(body);option(difficulty,"cpu","Computer difficulty","Level "+level(),this::difficulty);
