        for(String value:new String[]{"system","light","dark"}){boolean selected=appTheme.mode.equals(value);String label=value.substring(0,1).toUpperCase(Locale.ROOT)+value.substring(1);Button b=button(label,()->{if(!AppTheme.load(this).mode.equals(value)){AppTheme.setMode(this,value);recreate();}},false);b.setTextSize(12);b.setPadding(dp(4),dp(6),dp(4),dp(6));b.setSelected(selected);b.setBackground(shape(selected?SELECTED:BG,selected?ACCENT:LINE,10));inlineIcon(b,label,value,selected?ACCENT:LIGHT);b.setContentDescription("Display mode: "+label);modes.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));}parent.addView(modes);
