    private void difficulty(){
        LinearLayout body=col();pad(body,20,12,20,20);TextView title=text("Computer difficulty",20,LIGHT);body.addView(title);LinearLayout valueRow=row();TextView caption=text("Level",14,MUTED);valueRow.addView(caption,new LinearLayout.LayoutParams(0,-2,1));EditText value=new EditText(this);value.setSingleLine(true);value.setTextColor(LIGHT);value.setInputType(InputType.TYPE_CLASS_NUMBER);value.setText(Integer.toString(level()));value.setContentDescription("Enter difficulty level");valueRow.addView(value,new LinearLayout.LayoutParams(dp(72),dp(52)));body.addView(valueRow);
        SeekBar slider=new SeekBar(this);slider.setMax(99);slider.setProgress(level()-1);slider.setContentDescription("Computer difficulty level 1 to 100");body.addView(slider,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout ends=row();ends.addView(text("1 · Easiest",12,MUTED),new LinearLayout.LayoutParams(0,-2,1));ends.addView(text("100 · Strongest",12,MUTED));body.addView(ends);
        slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){prefs.edit().putInt("level",n+1).apply();if(!value.getText().toString().equals(Integer.toString(n+1)))value.setText(Integer.toString(n+1));}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
        Button done=button("Done",()->{try{int n=Integer.parseInt(value.getText().toString());if(n<1||n>100)throw new NumberFormatException();prefs.edit().putInt("level",n).apply();dialog.dismiss();showScreen(screen);}catch(NumberFormatException e){value.setError("Enter a level from 1 to 100");}},true);body.addView(done);sheet(body);
    }
    private void animation(){int[] values={0,100,200,300,500,800};String[] labels={"Off","100 ms","200 ms","300 ms","500 ms","800 ms"};int selected=0;for(int i=0;i<values.length;i++)if(values[i]==StudySettings.moveAnimationMillis(this))selected=i;dialog=new AlertDialog.Builder(this).setTitle("Move animation").setSingleChoiceItems(labels,selected,(d,n)->{StudySettings.setMoveAnimationMillis(this,values[n]);d.dismiss();showScreen("options");}).setNegativeButton("Cancel",null).show();}
